<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>롯데월드타워 건축 설계 과정</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
            background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
            color: #e0e0e0;
            overflow: hidden;
        }

        .container {
            display: flex;
            height: 100vh;
            gap: 1rem;
            padding: 1rem;
        }

        .left-panel {
            flex: 0 0 35%;
            display: flex;
            flex-direction: column;
            gap: 1rem;
            overflow-y: auto;
            background: rgba(0, 0, 0, 0.3);
            border-radius: 8px;
            padding: 1.5rem;
        }

        .right-panel {
            flex: 1;
            display: flex;
            flex-direction: column;
            gap: 1rem;
        }

        .header {
            text-align: center;
            margin-bottom: 1rem;
        }

        .header h1 {
            font-size: 1.8rem;
            margin-bottom: 0.5rem;
            background: linear-gradient(135deg, #00d4ff, #0099ff);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }

        .header p {
            font-size: 0.85rem;
            color: #888;
        }

        .model-name {
            font-size: 0.75rem;
            color: #666;
            text-align: center;
            margin-bottom: 1rem;
            font-style: italic;
        }

        .section {
            margin-bottom: 1.5rem;
        }

        .section-title {
            font-size: 1rem;
            font-weight: 600;
            color: #00d4ff;
            margin-bottom: 0.8rem;
            border-bottom: 2px solid #00d4ff;
            padding-bottom: 0.5rem;
        }

        .blueprint {
            background: rgba(0, 20, 40, 0.8);
            border: 1px solid #00d4ff;
            border-radius: 4px;
            padding: 1rem;
            margin-bottom: 0.8rem;
        }

        .blueprint-title {
            font-size: 0.9rem;
            font-weight: 600;
            color: #00d4ff;
            margin-bottom: 0.5rem;
        }

        .blueprint-content {
            font-size: 0.8rem;
            line-height: 1.6;
            color: #aaa;
        }

        .stage-buttons {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 0.5rem;
            margin-bottom: 1rem;
        }

        button {
            padding: 0.7rem;
            border: 1px solid #00d4ff;
            background: rgba(0, 212, 255, 0.1);
            color: #00d4ff;
            border-radius: 4px;
            cursor: pointer;
            font-size: 0.85rem;
            transition: all 0.3s ease;
        }

        button:hover {
            background: rgba(0, 212, 255, 0.2);
            box-shadow: 0 0 10px rgba(0, 212, 255, 0.3);
        }

        button.active {
            background: rgba(0, 212, 255, 0.4);
            box-shadow: 0 0 15px rgba(0, 212, 255, 0.5);
        }

        .controls {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 0.5rem;
            margin-top: 1rem;
        }

        .info-text {
            font-size: 0.8rem;
            color: #888;
            line-height: 1.5;
            margin-top: 0.5rem;
        }

        .canvas-container {
            flex: 1;
            background: rgba(0, 0, 0, 0.5);
            border-radius: 8px;
            overflow: hidden;
            border: 1px solid #00d4ff;
            position: relative;
        }

        canvas {
            width: 100%;
            height: 100%;
            display: block;
        }

        .canvas-label {
            position: absolute;
            top: 1rem;
            left: 1rem;
            background: rgba(0, 0, 0, 0.7);
            padding: 0.5rem 1rem;
            border-radius: 4px;
            font-size: 0.9rem;
            color: #00d4ff;
            pointer-events: none;
        }

        @media (max-width: 1024px) {
            .container {
                flex-direction: column;
            }

            .left-panel {
                flex: 0 0 auto;
                max-height: 40vh;
            }

            .canvas-container {
                flex: 1;
                min-height: 50vh;
            }

            .stage-buttons {
                grid-template-columns: 1fr;
            }
        }

        @media (prefers-reduced-motion: reduce) {
            * {
                animation: none !important;
                transition: none !important;
            }
        }

        .scrollable {
            overflow-y: auto;
            max-height: 100%;
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="left-panel">
            <div class="header">
                <h1>롯데월드타워</h1>
                <p>건축 설계 과정 인터랙티브 시각화</p>
            </div>

            <div class="model-name">Model: claude-haiku-4.5</div>

            <div class="section">
                <div class="section-title">기본 정보</div>
                <div class="blueprint">
                    <div class="blueprint-content">
                        <strong>높이:</strong> 555m<br>
                        <strong>층수:</strong> 지상 123층<br>
                        <strong>특징:</strong> 위로 갈수록 좁아지는 형태<br>
                        <strong>영감:</strong> 한국 도자기의 선
                    </div>
                </div>
            </div>

            <div class="section">
                <div class="section-title">도면</div>
                <div class="blueprint">
                    <div class="blueprint-title">배치도</div>
                    <div class="blueprint-content">
                        서울 송파구 위치<br>
                        기준층 면적: 약 6,000m²
                    </div>
                </div>
                <div class="blueprint">
                    <div class="blueprint-title">기준층 평면도</div>
                    <div class="blueprint-content">
                        원형 기둥 구조<br>
                        중심부 코어 배치<br>
                        외주 업무/상업 공간
                    </div>
                </div>
                <div class="blueprint">
                    <div class="blueprint-title">입면도</div>
                    <div class="blueprint-content">
                        점진적 테이퍼링<br>
                        수직 리브 패턴<br>
                        상부 첨탑 구조
                    </div>
                </div>
                <div class="blueprint">
                    <div class="blueprint-title">단면도</div>
                    <div class="blueprint-content">
                        중심 코어 구조<br>
                        외주 기둥 배치<br>
                        높이별 단면 변화
                    </div>
                </div>
            </div>

            <div class="section">
                <div class="section-title">설계 단계</div>
                <div class="stage-buttons">
                    <button id="stage1" class="stage-btn active">개념 설계</button>
                    <button id="stage2" class="stage-btn">기본 형태</button>
                    <button id="stage3" class="stage-btn">상세 설계</button>
                    <button id="stage4" class="stage-btn">완성 모델</button>
                </div>
                <div class="info-text" id="stageInfo">
                    기본 원형 기둥 형태로 시작하여 점진적으로 테이퍼링되는 형태로 발전합니다.
                </div>
            </div>

            <div class="section">
                <div class="section-title">조작 방법</div>
                <div class="controls">
                    <button onclick="resetView()">시점 초기화</button>
                    <button onclick="toggleRotation()">자동 회전</button>
                </div>
                <div class="info-text">
                    마우스: 드래그로 회전<br>
                    스크롤: 확대/축소<br>
                    터치: 핀치로 확대/축소
                </div>
            </div>
        </div>

        <div class="right-panel">
            <div class="canvas-container">
                <canvas id="canvas"></canvas>
                <div class="canvas-label" id="canvasLabel">3D 모델 뷰</div>
            </div>
        </div>
    </div>

    <script>
        let scene, camera, renderer, controls, model;
        let autoRotate = false;
        let currentStage = 1;

        const stageInfo = {
            1: "개념 설계: 기본 원형 기둥 형태로 시작합니다.",
            2: "기본 형태: 점진적 테이퍼링이 적용되기 시작합니다.",
            3: "상세 설계: 수직 리브와 세부 구조가 추가됩니다.",
            4: "완성 모델: 최종 설계된 롯데월드타워의 형태입니다."
        };

        function initThree() {
            const canvas = document.getElementById('canvas');
            const width = canvas.parentElement.clientWidth;
            const height = canvas.parentElement.clientHeight;

            scene = new THREE.Scene();
            scene.background = new THREE.Color(0x0a0e27);
            scene.fog = new THREE.Fog(0x0a0e27, 2000, 3500);

            camera = new THREE.PerspectiveCamera(75, width / height, 0.1, 5000);
            camera.position.set(400, 300, 400);

            renderer = new THREE.WebGLRenderer({ canvas, antialias: true });
            renderer.setSize(width, height);
            renderer.setPixelRatio(window.devicePixelRatio);
            renderer.shadowMap.enabled = true;

            controls = new THREE.OrbitControls(camera, canvas);
            controls.enableDamping = true;
            controls.dampingFactor = 0.05;
            controls.autoRotate = false;
            controls.autoRotateSpeed = 2;
            controls.minDistance = 200;
            controls.maxDistance = 1500;

            setupLighting();
            createModel(1);
            animate();

            window.addEventListener('resize', onWindowResize);
        }

        function setupLighting() {
            const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
            scene.add(ambientLight);

            const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
            directionalLight.position.set(500, 800, 500);
            directionalLight.castShadow = true;
            directionalLight.shadow.mapSize.width = 2048;
            directionalLight.shadow.mapSize.height = 2048;
            directionalLight.shadow.camera.far = 2000;
            directionalLight.shadow.camera.left = -1000;
            directionalLight.shadow.camera.right = 1000;
            directionalLight.shadow.camera.top = 1000;
            directionalLight.shadow.camera.bottom = -1000;
            scene.add(directionalLight);

            const pointLight = new THREE.PointLight(0x00d4ff, 0.5);
            pointLight.position.set(-500, 400, 500);
            scene.add(pointLight);
        }

        function createModel(stage) {
            if (model) {
                scene.remove(model);
            }

            model = new THREE.Group();

            const segments = 32;
            const height = 555;

            if (stage === 1) {
                // 개념 설계: 기본 원형
                const geometry = new THREE.CylinderGeometry(100, 100, height, segments);
                const material = new THREE.MeshPhongMaterial({
                    color: 0x00d4ff,
                    emissive: 0x004466,
                    shininess: 100,
                    wireframe: false
                });
                const cylinder = new THREE.Mesh(geometry, material);
                cylinder.castShadow = true;
                cylinder.receiveShadow = true;
                model.add(cylinder);

                // 기초
                const baseGeometry = new THREE.CylinderGeometry(120, 140, 30, segments);
                const baseMaterial = new THREE.MeshPhongMaterial({ color: 0x333333 });
                const base = new THREE.Mesh(baseGeometry, baseMaterial);
                base.position.y = -height / 2 - 15;
                base.castShadow = true;
                model.add(base);

            } else if (stage === 2) {
                // 기본 형태: 테이퍼링 시작
                const lathePoints = [];
                for (let i = 0; i <= 20; i++) {
                    const ratio = i / 20;
                    const radius = 100 * (1 - ratio * 0.4);
                    lathePoints.push(new THREE.Vector2(radius, (i / 20) * height - height / 2));
                }

                const geometry = new THREE.LatheGeometry(lathePoints, segments);
                const material = new THREE.MeshPhongMaterial({
                    color: 0x00a8cc,
                    emissive: 0x003344,
                    shininess: 100
                });
                const lathe = new THREE.Mesh(geometry, material);
                lathe.castShadow = true;
                lathe.receiveShadow = true;
                model.add(lathe);

                const baseGeometry = new THREE.CylinderGeometry(120, 140, 30, segments);
                const baseMaterial = new THREE.MeshPhongMaterial({ color: 0x333333 });
                const base = new THREE.Mesh(baseGeometry, baseMaterial);
                base.position.y = -height / 2 - 15;
                base.castShadow = true;
                model.add(base);

            } else if (stage === 3) {
                // 상세 설계: 리브 추가
                const lathePoints = [];
                for (let i = 0; i <= 20; i++) {
                    const ratio = i / 20;
                    const radius = 100 * (1 - ratio * 0.4);
                    lathePoints.push(new THREE.Vector2(radius, (i / 20) * height - height / 2));
                }

                const geometry = new THREE.LatheGeometry(lathePoints, segments);
                const material = new THREE.MeshPhongMaterial({
                    color: 0x0088aa,
                    emissive: 0x002244,
                    shininess: 100
                });
                const lathe = new THREE.Mesh(geometry, material);
                lathe.castShadow = true;
                lathe.receiveShadow = true;
                model.add(lathe);

                // 수직 리브
                for (let i = 0; i < 12; i++) {
                    const angle = (i / 12) * Math.PI * 2;
                    const ribGeometry = new THREE.BoxGeometry(8, height * 0.8, 4);
                    const ribMaterial = new THREE.MeshPhongMaterial({ color: 0x00d4ff });
                    const rib = new THREE.Mesh(ribGeometry, ribMaterial);
                    rib.position.x = Math.cos(angle) * 95;
                    rib.position.z = Math.sin(angle) * 95;
                    rib.position.y = 50;
                    rib.castShadow = true;
                    model.add(rib);
                }

                const baseGeometry = new THREE.CylinderGeometry(120, 140, 30, segments);
                const baseMaterial = new THREE.MeshPhongMaterial({ color: 0x333333 });
                const base = new THREE.Mesh(baseGeometry, baseMaterial);
                base.position.y = -height / 2 - 15;
                base.castShadow = true;
                model.add(base);

            } else if (stage === 4) {
                // 완성 모델: 상세 형태
                const lathePoints = [];
                for (let i = 0; i <= 30; i++) {
                    const ratio = i / 30;
                    const easeRatio = ratio * ratio * (3 - 2 * ratio);
                    const radius = 100 * (1 - easeRatio * 0.45);
                    lathePoints.push(new THREE.Vector2(radius, (i / 30) * height - height / 2));
                }

                const geometry = new THREE.LatheGeometry(lathePoints, segments);
                const material = new THREE.MeshPhongMaterial({
                    color: 0x0066ff,
                    emissive: 0x001166,
                    shininess: 120,
                    flatShading: false
                });
                const lathe = new THREE.Mesh(geometry, material);
                lathe.castShadow = true;
                lathe.receiveShadow = true;
                model.add(lathe);

                // 수직 리브 (더 많음)
                for (let i = 0; i < 24; i++) {
                    const angle = (i / 24) * Math.PI * 2;
                    const ribGeometry = new THREE.BoxGeometry(6, height * 0.85, 3);
                    const ribMaterial = new THREE.MeshPhongMaterial({ color: 0x00d4ff });
                    const rib = new THREE.Mesh(ribGeometry, ribMaterial);
                    rib.position.x = Math.cos(angle) * 98;
                    rib.position.z = Math.sin(angle) * 98;
                    rib.position.y = 40;
                    rib.castShadow = true;
                    model.add(rib);
                }

                // 첨탑
                const spireGeometry = new THREE.ConeGeometry(30, 100, 16);
                const spireMaterial = new THREE.MeshPhongMaterial({ color: 0x00d4ff });
                const spire = new THREE.Mesh(spireGeometry, spireMaterial);
                spire.position.y = height / 2 + 50;
                spire.castShadow = true;
                model.add(spire);

                const baseGeometry = new THREE.CylinderGeometry(120, 140, 30, segments);
                const baseMaterial = new THREE.MeshPhongMaterial({ color: 0x333333 });
                const base = new THREE.Mesh(baseGeometry, baseMaterial);
                base.position.y = -height / 2 - 15;
                base.castShadow = true;
                model.add(base);
            }

            scene.add(model);
        }

        function animate() {
            requestAnimationFrame(animate);

            if (autoRotate) {
                controls.autoRotate = true;
            } else {
                controls.autoRotate = false;
            }

            controls.update();
            renderer.render(scene, camera);
        }

        function onWindowResize() {
            const canvas = document.getElementById('canvas');
            const width = canvas.parentElement.clientWidth;
            const height = canvas.parentElement.clientHeight;

            camera.aspect = width / height;
            camera.updateProjectionMatrix();
            renderer.setSize(width, height);
        }

        function resetView() {
            camera.position.set(400, 300, 400);
            controls.target.set(0, 0, 0);
            controls.update();
        }

        function toggleRotation() {
            autoRotate = !autoRotate;
        }

        document.querySelectorAll('.stage-btn').forEach(btn => {
            btn.addEventListener('click', function() {
                document.querySelectorAll('.stage-btn').forEach(b => b.classList.remove('active'));
                this.classList.add('active');

                const stage = parseInt(this.id.replace('stage', ''));
                currentStage = stage;
                createModel(stage);
                document.getElementById('stageInfo').textContent = stageInfo[stage];
                document.getElementById('canvasLabel').textContent = `3D 모델 뷰 - ${['개념 설계', '기본 형태', '상세 설계', '완성 모델'][stage - 1]}`;
            });
        });

        if (typeof THREE !== 'undefined' && THREE.OrbitControls) {
            initThree();
        } else {
            const script = document.createElement('script');
            script.src = '../runtime/three-runtime.js';
            script.onload = initThree;
            document.head.appendChild(script);
        }
    </script>
</body>
</html>
